/*
 * Hero artwork: the door-wall drawing, as a single-colour alpha mask.
 *
 * Shipped as an inline base64 data URI rather than a file in /public. The
 * repo push tool available to this agent re-encodes file content as UTF-8
 * before base64-ing it for the GitHub API, which corrupts raw bytes above
 * 0x7F — confirmed against this exact asset (202,902 bytes on disk arrived
 * as 304,398 bytes on GitHub). Base64 text is pure ASCII, so inlining it
 * here sidesteps that transport bug entirely. If a future change needs to
 * swap this asset via a normal binary file commit (e.g. pushed from a real
 * git client instead of this tool), moving it back to /public and pointing
 * Hero.astro's mask-image at the file path is a safe, easy reversal.
 */
export const INK_DOORS_MASK = 'url("data:image/webp;base64,")';
